package com.parkcontrol.core.data.database

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import androidx.sqlite.db.SupportSQLiteDatabase
import com.parkcontrol.features.monthlyCustomers.data.local.dao.MonthlyCustomerDao
import com.parkcontrol.features.monthlyCustomers.data.local.entity.CustomerPlateEntity
import com.parkcontrol.features.monthlyCustomers.data.local.entity.MonthlyCustomerEntity
import com.parkcontrol.features.parking.data.local.dao.ParkingRecordDao
import com.parkcontrol.features.parking.data.local.entity.ParkingRecordEntity

@Database(
    entities = [MonthlyCustomerEntity::class, CustomerPlateEntity::class, ParkingRecordEntity::class],
    version = 7,
    exportSchema = false
)
abstract class AppDatabase : RoomDatabase() {

    abstract fun monthlyCustomerDao(): MonthlyCustomerDao

    abstract fun parkingRecordDao(): ParkingRecordDao

    companion object {
        private val CREATE_PHONE_UNIQUE_INDEX_CALLBACK = object : Callback() {
            override fun onCreate(db: SupportSQLiteDatabase) {
                super.onCreate(db)
                ensurePhoneUniqueIndex(db)
            }

            override fun onOpen(db: SupportSQLiteDatabase) {
                super.onOpen(db)
                ensurePhoneUniqueIndex(db)
            }
        }

        @Volatile
        private var INSTANCE: AppDatabase? = null

        fun getInstance(context: Context): AppDatabase {
            return INSTANCE ?: synchronized(this) {
                val instance = Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    "parkcontrol_database"
                )
                    .fallbackToDestructiveMigration(dropAllTables = true)
                    .addCallback(CREATE_PHONE_UNIQUE_INDEX_CALLBACK)
                    .build()
                INSTANCE = instance
                instance
            }
        }
    }
}

private fun ensurePhoneUniqueIndex(db: SupportSQLiteDatabase) {
    db.execSQL(
        "CREATE UNIQUE INDEX IF NOT EXISTS `index_monthly_customers_phone` ON `monthly_customers` (`phone`) WHERE TRIM(`phone`) != ''"
    )
}

package com.parkcontrol.core.data.database

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase
import androidx.sqlite.db.SupportSQLiteDatabase
import com.parkcontrol.features.monthlyCustomers.data.local.dao.MonthlyCustomerDao
import com.parkcontrol.features.monthlyCustomers.data.local.entity.CustomerPlateEntity
import com.parkcontrol.features.monthlyCustomers.data.local.entity.MonthlyCustomerEntity
import com.parkcontrol.features.parking.data.local.dao.ParkingRecordDao
import com.parkcontrol.features.parking.data.local.entity.ParkingRecordEntity

@Database(
    entities = [MonthlyCustomerEntity::class, CustomerPlateEntity::class, ParkingRecordEntity::class],
    version = 8,
    exportSchema = false
)
abstract class AppDatabase : RoomDatabase() {

    abstract fun monthlyCustomerDao(): MonthlyCustomerDao

    abstract fun parkingRecordDao(): ParkingRecordDao

    companion object {
        private val CREATE_UNIQUE_INDEXES_CALLBACK = object : Callback() {
            override fun onCreate(db: SupportSQLiteDatabase) {
                super.onCreate(db)
                ensureMonthlyCustomerUniqueIndexes(db)
            }

            override fun onOpen(db: SupportSQLiteDatabase) {
                super.onOpen(db)
                ensureMonthlyCustomerUniqueIndexes(db)
            }
        }

        @Volatile
        private var INSTANCE: AppDatabase? = null

        fun getInstance(context: Context): AppDatabase {
            return INSTANCE ?: synchronized(this) {
                val instance = Room.databaseBuilder(
                    context.applicationContext,
                    AppDatabase::class.java,
                    "parkcontrol_database"
                )
                    .fallbackToDestructiveMigration(dropAllTables = true)
                    .addCallback(CREATE_UNIQUE_INDEXES_CALLBACK)
                    .build()
                INSTANCE = instance
                instance
            }
        }
    }
}

private fun ensureMonthlyCustomerUniqueIndexes(db: SupportSQLiteDatabase) {
    db.execSQL(
        "CREATE UNIQUE INDEX IF NOT EXISTS `index_monthly_customers_phone` ON `monthly_customers` (`phone`) WHERE TRIM(`phone`) != ''"
    )
    db.execSQL(
        "CREATE UNIQUE INDEX IF NOT EXISTS `index_monthly_customers_email` ON `monthly_customers` (`email`) WHERE TRIM(`email`) != ''"
    )
}

package com.parkcontrol.features.monthlyCustomers.data.local.entity
import androidx.room.Entity import androidx.room.PrimaryKey
@Entity(tableName = "monthly_customers") data class MonthlyCustomerEntity( @PrimaryKey(autoGenerate = true) val id: Int = 0, val name: String, val phone: String, val isMonthly: Boolean = true, val monthlyFeeCents: Int? = null, val dueDay: Int? = null, val isActive: Boolean = true, val createdAt: Long, val updatedAt: Long )

package com.parkcontrol.features.monthlyCustomers.data.local.entity
import androidx.room.Entity import androidx.room.PrimaryKey
@Entity(tableName = "monthly_customers") data class MonthlyCustomerEntity( @PrimaryKey(autoGenerate = true) val id: Int = 0, val name: String, val phone: String, val email: String, val isMonthly: Boolean = true, val monthlyFeeCents: Int? = null, val dueDay: Int? = null, val isActive: Boolean = true, val createdAt: Long, val updatedAt: Long )

package com.parkcontrol.features.monthlyCustomers.data.local.mapper

import com.parkcontrol.features.monthlyCustomers.data.local.entity.CustomerPlateEntity
import com.parkcontrol.features.monthlyCustomers.data.local.entity.MonthlyCustomerEntity
import com.parkcontrol.features.monthlyCustomers.data.local.entity.MonthlyCustomerWithPlates
import com.parkcontrol.features.monthlyCustomers.domain.model.MonthlyCustomer

fun MonthlyCustomerWithPlates.toDomain(): MonthlyCustomer {
    val orderedPlates = plates
        .sortedWith(compareByDescending<CustomerPlateEntity> { it.isPrimary }.thenBy { it.id })
        .map { it.plate }

    return MonthlyCustomer(
        id = customer.id,
        name = customer.name,
        phone = customer.phone,
        isMonthly = customer.isMonthly,
        monthlyFeeCents = customer.monthlyFeeCents,
        dueDay = customer.dueDay,
        plates = orderedPlates,
        isActive = customer.isActive,
        createdAt = customer.createdAt,
        updatedAt = customer.updatedAt
    )
}

fun MonthlyCustomer.toEntity(): MonthlyCustomerEntity {
    return MonthlyCustomerEntity(
        id = id,
        name = name,
        phone = phone,
        isMonthly = isMonthly,
        monthlyFeeCents = monthlyFeeCents,
        dueDay = dueDay,
        isActive = isActive,
        createdAt = createdAt,
        updatedAt = updatedAt
    )
}

fun MonthlyCustomer.toPlateEntities(customerId: Int): List<CustomerPlateEntity> {
    val now = System.currentTimeMillis()
    return plates.mapIndexed { index, plate ->
        CustomerPlateEntity(
            customerId = customerId,
            plate = plate,
            isPrimary = index == 0,
            createdAt = now
        )
    }
}

fun List<MonthlyCustomerWithPlates>.toDomain(): List<MonthlyCustomer> {
    return this.map { it.toDomain() }
}

