        name: String,
        phone: String,
        email: String,
        isMonthly: Boolean,
        monthlyFee: String,
        dueDay: String,
        plates: List<String>
    ) {
        val normalizedPlates = plates
            .map { it.trim().uppercase() }
            .filter { it.isNotBlank() }
            .distinct()

        if (name.isBlank() || normalizedPlates.isEmpty()) {
            _uiState.value = _uiState.value.copy(
                errorMessage = "Nome e pelo menos uma placa sao obrigatorios"
            )
            return
        }

        val normalizedName = name.trim()
        val normalizedPhone = phone.filter(Char::isDigit).take(11)
        val normalizedEmail = email.trim().lowercase(Locale.ROOT)

        if (normalizedEmail.isNotBlank() && !emailRegex.matches(normalizedEmail)) {
            _uiState.value = _uiState.value.copy(
                errorMessage = "Email invalido"
            )
            return
        }

        val existingPlates = _uiState.value.customers
            .asSequence()
            .filter { customer -> customer.id != customerId }
            .flatMap { customer -> customer.plates.asSequence() }
            .map { plate -> plate.trim().uppercase() }
            .toSet()
        val duplicatePlate = normalizedPlates.firstOrNull { plate -> plate in existingPlates }
        if (duplicatePlate != null) {
            _uiState.value = _uiState.value.copy(
                errorMessage = "Placa ja cadastrada: $duplicatePlate"
            )
            return
        }

        if (normalizedPhone.isNotBlank()) {
            val phoneAlreadyUsed = _uiState.value.customers
                .any { customer ->
                    customer.id != customerId &&
                        customer.phone.filter(Char::isDigit).take(11) == normalizedPhone
                }
            if (phoneAlreadyUsed) {
                _uiState.value = _uiState.value.copy(
                    errorMessage = "Telefone ja cadastrado para outro cliente"
                )
                return
            }
        }

        if (normalizedEmail.isNotBlank()) {
            val emailAlreadyUsed = _uiState.value.customers
                .any { customer ->
                    customer.id != customerId &&
                        customer.email.trim().lowercase(Locale.ROOT) == normalizedEmail
                }
            if (emailAlreadyUsed) {
                _uiState.value = _uiState.value.copy(
                    errorMessage = "Email ja cadastrado para outro cliente"
                )
                return
            }
        }

        val monthlyFeeCents: Int?
        val dueDayValue: Int?

        if (isMonthly) {
            monthlyFeeCents = if (monthlyFee.isBlank()) {
                null
            } else {
                parseFeeToCents(monthlyFee) ?: run {
                    _uiState.value = _uiState.value.copy(errorMessage = "Valor mensal invalido")
                    return
                }
            }

            dueDayValue = if (dueDay.isBlank()) {
                null
            } else {
                dueDay.toIntOrNull()?.takeIf { it in allowedDueDays } ?: run {
                    _uiState.value = _uiState.value.copy(errorMessage = "Vencimento deve ser: 1, 5, 10, 15, 20 ou 25")
                    return
                }
            }
        } else {
            monthlyFeeCents = null
            dueDayValue = null
        }

        viewModelScope.launch {
            try {
                val existing = customerId?.let { getMonthlyCustomerByIdUseCase(it) }
                val now = System.currentTimeMillis()
                val customer = MonthlyCustomer(
                    id = existing?.id ?: 0,
                    name = normalizedName,
                    phone = normalizedPhone,
                    email = normalizedEmail,
                    isMonthly = isMonthly,
                    monthlyFeeCents = monthlyFeeCents,
                    dueDay = dueDayValue,
                    plates = normalizedPlates,
                    isActive = true,
                    createdAt = existing?.createdAt ?: now,
                    updatedAt = now
                )

                if (customerId == null) {
                    saveMonthlyCustomerUseCase(customer)
                } else {
                    updateMonthlyCustomerUseCase(customer)
                }

                _uiState.value = _uiState.value.copy(successMessage = if (customerId == null) "Cliente salvo com sucesso" else "Cliente atualizado com sucesso")
            } catch (_: Exception) {
                _uiState.value = _uiState.value.copy(errorMessage = "Erro ao salvar cliente")
            }
        }
    }

    fun inactivateCustomer(customerId: Int) {
        viewModelScope.launch {
            try {
                inactivateMonthlyCustomerUseCase(customerId)
                _uiState.value = _uiState.value.copy(successMessage = "Cliente inativado com sucesso")
            } catch (_: Exception) {
                _uiState.value = _uiState.value.copy(errorMessage = "Erro ao inativar cliente")
            }
        }
    }

    fun clearErrorMessage() {
        _uiState.value = _uiState.value.copy(errorMessage = null)
    }

    fun clearSuccessMessage() {
        _uiState.value = _uiState.value.copy(successMessage = null)
    }

    private fun parseFeeToCents(input: String): Int? {
        val digitsOnly = input.filter(Char::isDigit)
        if (digitsOnly.isNotEmpty() && digitsOnly.length == input.trim().length) {
            return digitsOnly.toLongOrNull()?.takeIf { it <= Int.MAX_VALUE }?.toInt()
        }

        val normalized = input
            .replace("R$", "")
            .trim()
            .replace(',', '.')

        val value = normalized.toBigDecimalOrNull() ?: return null
        if (value < BigDecimal.ZERO) return null

        return value
            .multiply(BigDecimal(100))
            .setScale(0, RoundingMode.HALF_UP)
            .toInt()
    }
}

package com.parkcontrol.features.parking.data.local.dao
import androidx.room.Dao import androidx.room.Insert import androidx.room.OnConflictStrategy import androidx.room.Query import androidx.room.Transaction import androidx.room.Update import com.parkcontrol.features.monthlyCustomers.data.local.entity.CustomerPlateEntity import com.parkcontrol.features.monthlyCustomers.data.local.entity.MonthlyCustomerEntity import com.parkcontrol.features.parking.data.local.entity.ParkingRecordEntity import kotlinx.coroutines.flow.Flow
@Dao interface ParkingRecordDao {
@Query("SELECT * FROM parking_records ORDER BY entryTimeMillis DESC") fun observeParkingRecords(): Flow<List<ParkingRecordEntity>>
@Query("SELECT * FROM parking_records WHERE id = :recordId LIMIT 1") suspend fun getParkingRecordById(recordId: String): ParkingRecordEntity?
@Insert(onConflict = OnConflictStrategy.ABORT) suspend fun insertParkingRecord(record: ParkingRecordEntity)
@Update suspend fun updateParkingRecord(record: ParkingRecordEntity)
@Query( """ SELECT mc.id FROM monthly_customers mc INNER JOIN customer_plates cp ON cp.customerId = mc.id WHERE UPPER(TRIM(cp.plate)) = UPPER(TRIM(:plate)) ORDER BY mc.isActive DESC, cp.isPrimary DESC, mc.id DESC LIMIT 1 """ ) suspend fun getCustomerIdByPlate(plate: String): Int?
@Insert(onConflict = OnConflictStrategy.ABORT) suspend fun insertCustomer(customer: MonthlyCustomerEntity): Long
@Insert(onConflict = OnConflictStrategy.ABORT) suspend fun insertPlate(plate: CustomerPlateEntity)
@Transaction suspend fun insertParkingRecordEnsuringCustomer(record: ParkingRecordEntity) { val normalizedPlate = record.licensePlate.trim().uppercase() val normalizedPhone = record.phone.trim() val customerId = getCustomerIdByPlate(normalizedPlate) ?: createFallbackCustomer( plate = normalizedPlate, phone = normalizedPhone )
insertParkingRecord( record.copy( customerId = customerId, licensePlate = normalizedPlate, phone = normalizedPhone ) ) }
@Query( """ SELECT EXISTS ( SELECT 1 FROM parking_records WHERE UPPER(TRIM(licensePlate)) = UPPER(TRIM(:licensePlate)) AND status = 'ESTACIONADO' LIMIT 1 ) """ ) suspend fun hasActiveParking(licensePlate: String): Boolean
private suspend fun createFallbackCustomer(plate: String, phone: String): Int { val now = System.currentTimeMillis() val customerId = insertCustomer( MonthlyCustomerEntity( name = "não informado", phone = phone, isMonthly = false, monthlyFeeCents = null, dueDay = null, isActive = true, createdAt = now, updatedAt = now ) ).toInt()
insertPlate( CustomerPlateEntity( customerId = customerId, plate = plate, isPrimary = true, createdAt = now ) )
return customerId } }

package com.parkcontrol.features.parking.data.local.dao
import androidx.room.Dao import androidx.room.Insert import androidx.room.OnConflictStrategy import androidx.room.Query import androidx.room.Transaction import androidx.room.Update import com.parkcontrol.features.monthlyCustomers.data.local.entity.CustomerPlateEntity import com.parkcontrol.features.monthlyCustomers.data.local.entity.MonthlyCustomerEntity import com.parkcontrol.features.parking.data.local.entity.ParkingRecordEntity import kotlinx.coroutines.flow.Flow
@Dao interface ParkingRecordDao {
@Query("SELECT * FROM parking_records ORDER BY entryTimeMillis DESC") fun observeParkingRecords(): Flow<List<ParkingRecordEntity>>
@Query("SELECT * FROM parking_records WHERE id = :recordId LIMIT 1") suspend fun getParkingRecordById(recordId: String): ParkingRecordEntity?
@Insert(onConflict = OnConflictStrategy.ABORT) suspend fun insertParkingRecord(record: ParkingRecordEntity)
@Update suspend fun updateParkingRecord(record: ParkingRecordEntity)
@Query( """ SELECT mc.id FROM monthly_customers mc INNER JOIN customer_plates cp ON cp.customerId = mc.id WHERE UPPER(TRIM(cp.plate)) = UPPER(TRIM(:plate)) ORDER BY mc.isActive DESC, cp.isPrimary DESC, mc.id DESC LIMIT 1 """ ) suspend fun getCustomerIdByPlate(plate: String): Int?
@Insert(onConflict = OnConflictStrategy.ABORT) suspend fun insertCustomer(customer: MonthlyCustomerEntity): Long
@Insert(onConflict = OnConflictStrategy.ABORT) suspend fun insertPlate(plate: CustomerPlateEntity)
@Transaction suspend fun insertParkingRecordEnsuringCustomer(record: ParkingRecordEntity) { val normalizedPlate = record.licensePlate.trim().uppercase() val normalizedPhone = record.phone.trim() val customerId = getCustomerIdByPlate(normalizedPlate) ?: createFallbackCustomer( plate = normalizedPlate, phone = normalizedPhone )
insertParkingRecord( record.copy( customerId = customerId, licensePlate = normalizedPlate, phone = normalizedPhone ) ) }
@Query( """ SELECT EXISTS ( SELECT 1 FROM parking_records WHERE UPPER(TRIM(licensePlate)) = UPPER(TRIM(:licensePlate)) AND status = 'ESTACIONADO' LIMIT 1 ) """ ) suspend fun hasActiveParking(licensePlate: String): Boolean
private suspend fun createFallbackCustomer(plate: String, phone: String): Int { val now = System.currentTimeMillis() val customerId = insertCustomer( MonthlyCustomerEntity( name = "não informado", phone = phone, email = "", isMonthly = false, monthlyFeeCents = null, dueDay = null, isActive = true, createdAt = now, updatedAt = now ) ).toInt()
insertPlate( CustomerPlateEntity( customerId = customerId, plate = plate, isPrimary = true, createdAt = now ) )
return customerId } }
